'use strict';
(()=>{const status=document.querySelector('#form-status'),button=document.querySelector('#subscription-action'),intro=document.querySelector('#subscription-intro');const match=location.hash.match(/^#(confirm|unsubscribe)=([a-f0-9]{64})$/);history.replaceState(null,'',location.pathname);if(!match)return;const[,action,token]=match;intro.textContent=action==='confirm'?'Confirm your address to receive fluqon.qpon deal alerts.':'Leave the list. No login. No questions.';button.hidden=false;button.textContent=action==='confirm'?'confirm.fluq_':'unsubscribe.fluq_';button.addEventListener('click',async()=>{button.disabled=true;try{const r=await fetch('/api/subscription/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token})});const result=await r.json();if(!r.ok)throw Error(result.error);status.textContent=result.message;button.hidden=true;}catch(error){status.textContent=error.message;button.disabled=false;}});})();
